package com.ethk3.novaonepro.strategyv2;
import java.io.*;import java.lang.reflect.*;import java.nio.*;import java.util.*;
public final class R26RelationStatisticsTest {
 static void check(boolean x,String why){if(!x)throw new AssertionError(why);}
 static OnlineModelsSU2.RelBayes kernel(FamilyF21KernelR26 m)throws Exception{Field f=FamilyF21KernelR26.class.getDeclaredField("model");f.setAccessible(true);return (OnlineModelsSU2.RelBayes)f.get(m);}
 static OnlineModelsSU2.RelBayes old(){return (OnlineModelsSU2.RelBayes)ModelReplaySU2.build("RELBAYES",ModelEvolutionSU2.centralParams("RELBAYES"));}
 static byte[] save(OnlineModelsSU2.Model m)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();m.write(new DataOutputStream(b));return b.toByteArray();}
 static byte[] projection(byte[] b){return Arrays.copyOfRange(b,4,b.length-9);}
 static FamilyF21KernelR26 restore(byte[] b)throws Exception{FamilyF21KernelR26 m=new FamilyF21KernelR26();m.read(new DataInputStream(new ByteArrayInputStream(b)));return m;}
 static int[] draw(Random r){int[] d=new int[10];for(int i=0;i<10;i++)d[i]=i+1;for(int i=9;i>0;i--){int j=r.nextInt(i+1),v=d[i];d[i]=d[j];d[j]=v;}return d;}
 static double loss(OnlineModelsSU2.RelBayes counts,OnlineModelsSU2.RelBayes context,int[] target){
  double value=0;for(int p=0;p<10;p++){double[] score=new double[10];for(int q=0;q<10;q++)for(int l=0;l<context.L;l++){int x=context.recent[(context.seen-context.lags[l])%context.maxlag][q]-1;int[] ns={x,(x+1)%10,(x+9)%10,9-x};for(int kind=0;kind<4;kind++){int i=((p*10+q)*context.L+l)*4+kind;double rho=(counts.s[i]+.1*counts.kappa)/(counts.n[i]+counts.kappa);score[ns[kind]]+=Math.max(0,Math.log(rho/.1)/counts.temp);}}double z=0;for(double x:score)z+=Math.exp(x);value+=(Math.log(z)-score[target[p]-1])/10;}return value;
 }
 public static void main(String[] args)throws Exception{
  FamilyF21KernelR26 m=new FamilyF21KernelR26();OnlineModelsSU2.RelBayes reference=old();Random random=new Random(2621);long updates=0;double maxLossError=0;java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");
  for(int i=0;i<600;i++){
   if(i==100||i==410){m.resetTemporalContext();TemporalResetR26.reset(reference);check(m.completedTrainingUpdates()==updates&&m.lastStatisticalTrainingStep()==null,"gap erased learning counter");}
   byte[] before=save(m);FamilyF21KernelR26 frozen=restore(before);OnlineModelsSU2.RelBayes prior=kernel(frozen);boolean train=prior.seen>=prior.maxlag;int[] target=draw(random);reference.update(target);m.update(target);OnlineModelsSU2.RelBayes actual=kernel(m);
   check(Arrays.equals(save(reference),projection(save(m))),"old complete counts/context arithmetic changed");float[][] pa=new float[10][10],pb=new float[10][10];float[] sa=new float[3],sb=new float[3];reference.predict(pa,sa);m.predict(pb,sb);check(Arrays.deepEquals(pa,pb)&&Arrays.equals(sa,sb),"old predictions/features differ");digest.update(projection(save(m)));
   if(train){updates++;StatisticalTrainingDiagnosticsR26.Step step=m.lastStatisticalTrainingStep();check(step!=null&&step.update==updates,"missing actual statistic update");double stats=0,params=0;for(int k=0;k<prior.s.length;k++){double ds=actual.s[k]-prior.s[k],dn=actual.n[k]-prior.n[k];stats+=ds*ds+dn*dn;double a=(actual.s[k]+.1*actual.kappa)/(actual.n[k]+actual.kappa),b=(prior.s[k]+.1*prior.kappa)/(prior.n[k]+prior.kappa);params+=(a-b)*(a-b);}check(step.statisticDeltaNorm==Math.sqrt(stats)&&step.parameterDeltaNorm==Math.sqrt(params),"statistic/posterior deltas differ");maxLossError=Math.max(maxLossError,Math.max(Math.abs(step.lossBefore-loss(prior,prior,target)),Math.abs(step.lossAfter-loss(actual,prior,target))));check(maxLossError<1e-12,"loss used advanced context");FamilyF21KernelR26 alternative=restore(before);alternative.update(draw(random));check(step.inputHash.equals(alternative.lastStatisticalTrainingStep().inputHash),"label leaked into input hash");}else check(m.lastStatisticalTrainingStep()==null&&m.completedTrainingUpdates()==updates,"context fill counted as training");
   frozen.update(target);check(Arrays.equals(save(m),save(frozen)),"restored next update differs");if(i==300)m=restore(save(m));
  }
  byte[] good=save(m);FamilyF21KernelR26 legacy=restore(projection(good));check(legacy.completedTrainingUpdates()==0&&legacy.optimizerProtocol().endsWith("UNKNOWN_PRIOR_UPDATES_COUNTED_SINCE_IMPORT"),"legacy context clock fabricated lifetime");check(Arrays.equals(projection(good),projection(save(legacy))),"legacy state lost");int[] future=draw(random);m.update(future);legacy.update(future);check(Arrays.equals(projection(save(m)),projection(save(legacy)))&&legacy.completedTrainingUpdates()==1,"legacy continuation differs");
  m=restore(good);for(int type=0;type<3;type++){byte[] bad=good.clone();if(type==0)ByteBuffer.wrap(bad).putDouble(8,Double.NaN);if(type==1)bad=Arrays.copyOf(bad,bad.length-2);if(type==2)bad[bad.length-1]=2;try{m.read(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("corrupt state accepted");}catch(IOException expected){}check(Arrays.equals(good,save(m)),"corrupt restore changed state");}
  for(int budget:new int[]{1,20,400}){m=restore(good);ExecutionBudgetR26.enter(new BudgetTokenSU1(30000,budget,()->false));boolean yielded=false;try{m.update(future);}catch(BudgetTokenSU1.Yield expected){yielded=true;}finally{ExecutionBudgetR26.leave();}check(yielded&&Arrays.equals(good,save(m))&&m.lastStatisticalTrainingStep()==null,"mid-count cancellation committed partial state");}
  if(args.length>0)java.nio.file.Files.write(java.nio.file.Paths.get(args[0]),good);StringBuilder hex=new StringBuilder();for(byte b:digest.digest())hex.append(String.format("%02x",b&255));
  System.out.println("R26_RELATION_STATISTICS_PASS|samples=600|updates="+updates+"|maxLossError="+maxLossError+"|fullOldNumericProjectionHash="+hex+"|warmupNotTraining=true|oldCounterUnknown=true|midUpdateCancelAndCorruptRestoreAtomic=true|scope=SYNTHETIC_NOT_NATURAL_QUALITY");
 }
}
